#include "linked_list.h"
#include <cassert>
#include <stdexcept>
#include <string>

int main() {
    using linked_list::List;

    // erase missing value / duplicate handling
    List<int> l;
    assert(!l.erase(1));
    l.push(5); l.push(5); l.push(7); l.push(5);
    assert(l.erase(5));
    assert(l.count() == 3);
    assert(l.shift() == 5 && l.shift() == 7 && l.pop() == 5);
    assert(l.count() == 0);

    // copy independence and deep copy
    List<int> a;
    a.push(1); a.push(2);
    List<int> b(a);
    assert(b.count() == 2);
    b.push(3);
    assert(a.count() == 2 && b.count() == 3);
    assert(a.pop() == 2 && b.pop() == 3);

    // move leaves source empty and usable
    List<int> c(std::move(b));
    assert(c.count() == 2 && b.count() == 0);
    b.push(9);
    assert(b.pop() == 9);

    // copy assignment and self-assignment safety
    List<int> d;
    d.push(42);
    a = d;
    assert(a.count() == 1 && a.pop() == 42);
    a.push(8);
    a = a;
    assert(a.count() == 1 && a.pop() == 8);

    // non-trivial element type (strings)
    List<std::string> s;
    s.unshift("b"); s.unshift("a"); s.push("c");
    assert(s.count() == 3);
    assert(s.erase("b"));
    assert(s.shift() == "a" && s.pop() == "c");

    // empty pop/shift throw
    bool threw = false;
    try { l.pop(); } catch (const std::out_of_range&) { threw = true; }
    assert(threw);
    threw = false;
    try { l.shift(); } catch (const std::out_of_range&) { threw = true; }
    assert(threw);

    // interleaved operations keep count consistent
    List<int> e;
    for (int i = 0; i < 100; ++i) e.push(i);
    for (int i = 0; i < 50; ++i) assert(e.shift() == i);
    for (int i = 0; i < 25; ++i) e.unshift(1000 + i);
    assert(e.count() == 75);
    for (int i = 0; i < 25; ++i) assert(e.pop() == 99 - i);
    assert(e.count() == 50);
    return 0;
}
